```js
// page after the last item seen
db.products.find({ $or: [
  { price: { $gt: lastPrice } },
  { price: lastPrice, _id: { $gt: lastId } }
] }).sort({ price: 1, _id: 1 }).limit(20)
```

```js
// mark every T-shirt line as backordered
db.orders.updateMany(
  { "items.sku": "TEE-01" },
  { $set: { "items.$[it].status": "backordered" } },
  { arrayFilters: [{ "it.sku": "TEE-01" }] }
)

// keep only the last 10 viewed products
db.users.updateOne({ _id: uid },
  { $push: { recentlyViewed: { $each: [pid], $slice: -10 } } })
```

```js
const res = await db.collection('products').findOneAndUpdate(
  { _id: productId, stock: { $gte: qty } },
  { $inc: { stock: -qty } },
  { returnDocument: 'after' }
)
if (!res) throw new Error('Out of stock')
```
(Node driver v6+ में, `findOneAndUpdate` default में सीधे document लौटाता है।) अगर stock घटाना और order बनाना साथ में succeed या fail होने चाहिए, तो दोनों को एक **transaction** में wrap करें, या ऐसा design करें कि दूसरा step fail होने पर order को compensate किया जा सके।
